INSERT INTO `oc_theme` (`theme_id`, `store_id`, `route`, `code`, `status`, `date_added`) VALUES ('8', '0', 'common/header', '<!DOCTYPE html>\n<html dir=\"{{ direction }}\" lang=\"{{ lang }}\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n  <title>{{ title }}</title>\n  <base href=\"{{ base }}\"/>\n  {% if description %}\n    <meta name=\"description\" content=\"{{ description }}\"/>\n  {% endif %}\n  {% if keywords %}\n    <meta name=\"keywords\" content=\"{{ keywords }}\"/>\n  {% endif %}\n  <script src=\"{{ jquery }}\" type=\"text/javascript\"></script>\n  <link href=\"{{ bootstrap }}\" type=\"text/css\" rel=\"stylesheet\" media=\"screen\"/>\n  <link href=\"{{ icons }}\" rel=\"stylesheet\" type=\"text/css\"/>\n  <link href=\"{{ stylesheet }}\" type=\"text/css\" rel=\"stylesheet\"/>\n  {% if rtl_stylesheet %}\n    <link href=\"{{ rtl_stylesheet }}\" type=\"text/css\" rel=\"stylesheet\"/>\n  {% endif %}\n  <link href=\"catalog/view/stylesheet/theme-modern-base.css?v=4\" type=\"text/css\" rel=\"stylesheet\"/>\n  <link href=\"catalog/view/stylesheet/theme-persiantvbox.css?v=4\" type=\"text/css\" rel=\"stylesheet\"/>\n  <script src=\"catalog/view/javascript/common.js\" type=\"text/javascript\"></script>\n  {% if icon %}\n    <link rel=\"icon\" href=\"{{ icon }}\" type=\"image/png\">\n  {% endif %}\n  {% for style in styles %}\n    <link href=\"{{ style.href }}\" type=\"text/css\" rel=\"{{ style.rel }}\" media=\"{{ style.media }}\"/>\n  {% endfor %}\n  {% for script in scripts %}\n    <script src=\"{{ script.href }}\" type=\"text/javascript\"></script>\n  {% endfor %}\n  {% for link in links %}\n    <link href=\"{{ link.href }}\" rel=\"{{ link.rel }}\"/>\n  {% endfor %}\n  {% for analytic in analytics %}\n    {{ analytic }}\n  {% endfor %}\n</head>\n<body class=\"theme-persiantvbox\">\n<div id=\"container\">\n  <div id=\"alert\"></div>\n  <header class=\"theme-ptv-nav\">\n    <div class=\"container theme-ptv-nav-row\">\n      <div id=\"logo\">\n        {% if logo %}\n          <a href=\"{{ home }}\"><img src=\"{{ logo }}\" title=\"{{ name }}\" alt=\"{{ name }}\" class=\"img-fluid\"/></a>\n        {% else %}\n          <h1><a href=\"{{ home }}\">{{ name }}</a></h1>\n        {% endif %}\n      </div>\n      <div class=\"theme-ptv-nav-menu\">\n        {{ menu }}\n      </div>\n      <div class=\"theme-ptv-nav-actions\">\n        <div class=\"theme-ptv-search-toggle\" role=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#theme-ptv-search\"><i class=\"fa-solid fa-magnifying-glass\"></i></div>\n        <div class=\"d-none d-md-block\">{{ currency }}</div>\n        <div class=\"d-none d-md-block\">{{ language }}</div>\n        <div class=\"dropdown\">\n          <span role=\"button\" class=\"dropdown-toggle\" data-bs-toggle=\"dropdown\"><i class=\"fa-solid fa-user\"></i></span>\n          <ul class=\"dropdown-menu dropdown-menu-end\">\n            {% if not logged %}\n              <li><a href=\"{{ register }}\" class=\"dropdown-item\">{{ text_register }}</a></li>\n              <li><a href=\"{{ login }}\" class=\"dropdown-item\">{{ text_login }}</a></li>\n            {% else %}\n              <li><a href=\"{{ account }}\" class=\"dropdown-item\">{{ text_account }}</a></li>\n              <li><a href=\"{{ order }}\" class=\"dropdown-item\">{{ text_order }}</a></li>\n              <li><a href=\"{{ transaction }}\" class=\"dropdown-item\">{{ text_transaction }}</a></li>\n              <li><a href=\"{{ download }}\" class=\"dropdown-item\">{{ text_download }}</a></li>\n              <li><a href=\"{{ logout }}\" class=\"dropdown-item\">{{ text_logout }}</a></li>\n            {% endif %}\n          </ul>\n        </div>\n        <div id=\"cart\">{{ cart }}</div>\n        <a href=\"{{ checkout }}\" class=\"theme-ptv-pill-btn d-none d-lg-inline-block\">{{ text_checkout }}</a>\n      </div>\n    </div>\n    <div class=\"collapse container\" id=\"theme-ptv-search\">{{ search }}</div>\n  </header>\n  <main>\n', '1', '2026-09-07 19:55:32');
INSERT INTO `oc_theme` (`theme_id`, `store_id`, `route`, `code`, `status`, `date_added`) VALUES ('9', '0', 'common/home', '{{ header }}\n<div class=\"theme-persiantvbox-hero\">\n  <div class=\"theme-persiantvbox-glow\"></div>\n  <div class=\"theme-persiantvbox-bar theme-persiantvbox-bar-top\"></div>\n  <div class=\"theme-persiantvbox-content\">\n    <h1>{{ name }}</h1>\n    <p>{{ text_hero_tagline }}</p>\n    <a href=\"index.php?route=product/category\" class=\"btn btn-primary me-2\">{{ button_hero_products }}</a>\n    <a href=\"index.php?route=product/special\" class=\"btn btn-outline-light\">{{ button_hero_special }}</a>\n  </div>\n  <div class=\"theme-persiantvbox-bar theme-persiantvbox-bar-bottom\"></div>\n</div>\n{% if home_products %}\n  <div class=\"theme-persiantvbox-row\">\n    <div class=\"container\">\n      <h2>{{ text_new_products_heading }}</h2>\n      <div class=\"theme-persiantvbox-poster-track\">\n        {% for product in home_products %}\n          <a href=\"{{ product.href }}\" class=\"theme-persiantvbox-poster\" style=\"background-image:url(\'{{ product.thumb }}\');\">\n            <span class=\"theme-persiantvbox-poster-overlay\">\n              <span class=\"theme-persiantvbox-poster-title\">{{ product.name }}</span>\n              {% if product.price %}<span class=\"theme-persiantvbox-poster-price\">{{ product.price }}</span>{% endif %}\n            </span>\n          </a>\n        {% endfor %}\n      </div>\n    </div>\n  </div>\n{% endif %}\n<div id=\"common-home\" class=\"container\">\n  <div class=\"row\">{{ column_left }}\n    <div id=\"content\" class=\"col\">{{ content_top }}{{ content_bottom }}</div>\n    {{ column_right }}</div>\n</div>\n{{ footer }}\n', '1', '2026-09-07 19:55:32');
